'use strict';
const $=s=>document.querySelector(s);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={user:null,csrf:'',courses:[],cid:null,page:'dashboard',progress:null,topics:[],quiz:null,algorithm:null,step:0,recognition:null,voiceTranscript:'',health:null};
const icons={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',path:'M5 4v12a4 4 0 0 0 4 4h10M15 16l4 4-4 4M2 4h6M3 10h4',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',quiz:'M6 3h12v18H6zM9 7h6M9 11h6M9 15h3',graph:'M6 6l12 5M6 6l2 13M18 11 8 19M3 3h6v6H3zM15 8h6v6h-6zM5 16h6v6H5z',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4M8 14h2M14 14h2',chart:'M4 3v18h17M8 17v-5M13 17V8M18 17V4',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M6 6a3 3 0 1 0 6 0 3 3 0 0 0-6 0M17 3a3 3 0 0 1 0 6M22 21v-3a4 4 0 0 0-3-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M4 12h16M14 6l6 6-6 6',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6zM8 12l3 3 5-6',code:'m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18',moon:'M21 12.8A8.5 8.5 0 1 1 11.2 3a6.8 6.8 0 0 0 9.8 9.8z',menu:'M4 7h16M4 12h16M4 17h16'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;}
function brand(){return '<a class="brand" href="/" aria-label="CampusPath home"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M6 17 12 7l6 10"/><circle cx="6" cy="17" r="2"/><circle cx="12" cy="7" r="2"/><circle cx="18" cy="17" r="2"/></svg></span><span>CampusPath<em>AI</em></span></a>';}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(state.toast);state.toast=setTimeout(()=>$('#toast').style.display='none',5000);}
async function api(url,options={}){
 const headers={...options.headers};if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}if(state.csrf)headers['X-CSRF-Token']=state.csrf;
 const signal=options.signal||(!options.method||options.method==='GET'?AbortSignal.timeout(10000):undefined);
 let response,data;
 try{response=await fetch('/api'+url,{...options,signal,headers,credentials:'same-origin'});data=await response.json();}
 catch(err){
  if(signal?.reason?.name==='TimeoutError')throw new Error('The server took too long to respond. Please try again.');
  if(err instanceof SyntaxError)throw new Error('The server returned an unreadable response.');
  throw err;
 }
 if(!response.ok){if(response.status===401 && state.user){stopVoice();clearInterval(state.quizTimer);clearInterval(state.oralTimer);state.user=null;state.csrf='';state.navTicket=(state.navTicket||0)+1;authPage('login');}throw new Error(Array.isArray(data.detail)?data.detail.map(x=>x.msg).join('; '):data.detail||'Request failed.');}return data;
}
const post=(url,body={})=>api(url,{method:'POST',body});
function publicHeader(){return `<header class="public-header">${brand()}<div class="actions"><button class="ghost" data-action="theme" aria-label="Switch light or dark theme" title="Switch light or dark theme">${icon('moon')}</button><button class="ghost hide-mobile" data-action="login">Sign in</button><button data-action="register">Create account ${icon('arrow')}</button></div></header>`;}
function landing(){
 $('#root').innerHTML=publicHeader()+`<main id="main"><section class="hero"><div><span class="pill">A clearer path from learning to understanding</span><h1>Every student<br>learns differently.<br><span>CampusPath adapts.</span></h1><p class="muted">Understand where you are. Discover what comes next. A course-connected learning space that grows with your knowledge.</p><div class="actions"><button data-action="demo-student">Explore student demo ${icon('arrow')}</button><button class="secondary" data-action="demo-teacher">Teacher demo</button></div><p class="footer-note">Private student progress · Explainable recommendations · Faculty oversight</p></div><div class="hero-visual"><div class="row"><span class="eyebrow">YOUR KNOWLEDGE, CONNECTED</span><span class="tag green">Sample view</span></div><div class="orbit"><div class="orb">🎓</div></div><div class="row"><h3>Your next breakthrough</h3>${icon('spark')}</div><div class="topic-row"><div class="row"><span>Foundations · Chapter 1</span><small>90%</small></div><div class="progress"><span style="width:90%"></span></div></div><div class="topic-row"><div class="row"><span>Key formulas · Chapter 3</span><small>48%</small></div><div class="progress"><span class="low" style="width:48%"></span></div></div><div class="alert">Start with Chapter 3. It is a prerequisite for the next unit. Works the same for any subject your teacher uploads.</div><small>Illustrative demo starting values, not measured results.</small></div></section><section class="features"><article class="feature">${icon('graph')}<h2 class="subhead">See the connections.</h2><p>A course knowledge graph links concepts to their prerequisites, so you know where to begin.</p></article><article class="feature">${icon('path')}<h2 class="subhead">Practice with purpose.</h2><p>Assessment evidence updates your knowledge model and creates a reasoned path forward.</p></article><article class="feature">${icon('shield')}<h2 class="subhead">Built around trust.</h2><p>Your progress stays yours. Verified teachers see learners enrolled in their own courses.</p></article></section><section class="departments" aria-label="Works for every department"><h2 class="subhead">Built for every department 🎓</h2><p class="muted">A teacher uploads a book, slides or notes. CampusPath builds the concepts, practice, quizzes and viva questions from that material, whatever the subject.</p><div class="dept-chips"><span class="dept-chip"><b aria-hidden="true">💻</b>Computer Science</span><span class="dept-chip"><b aria-hidden="true">🧪</b>Chemistry</span><span class="dept-chip"><b aria-hidden="true">🧬</b>Biology</span><span class="dept-chip"><b aria-hidden="true">🩺</b>Medicine & Nursing</span><span class="dept-chip"><b aria-hidden="true">⚖️</b>Law</span><span class="dept-chip"><b aria-hidden="true">📊</b>Business & Accounting</span><span class="dept-chip"><b aria-hidden="true">📐</b>Mathematics</span><span class="dept-chip"><b aria-hidden="true">⚙️</b>Engineering</span><span class="dept-chip"><b aria-hidden="true">🏛️</b>History & Social Sciences</span><span class="dept-chip"><b aria-hidden="true">🎨</b>Arts & Design</span><span class="dept-chip"><b aria-hidden="true">🌍</b>Languages & Literature</span><span class="dept-chip"><b aria-hidden="true">🧑‍🏫</b>Education</span></div></section></main><footer class="public-foot">CampusPath AI · Learning with evidence, guided by educators.</footer>`;
}
function field(label,name,type='text',attrs='',value=''){return `<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${e(value)}" ${attrs}></div>`;}
function authAside(){return `<aside class="auth-aside" aria-label="About CampusPath"><span class="eyebrow">Course-connected learning</span><h2>Know where you stand, and what to learn next.</h2><ul class="auth-points"><li>${icon('graph')}<span>A prerequisite-aware concept map for every course.</span></li><li>${icon('shield')}<span>Only you and your enrolled teachers see your progress.</span></li><li>${icon('mic')}<span>Practice viva and assigned viva, clearly labelled.</span></li></ul></aside>`;}
function authPage(kind='login'){
 const register=kind==='register';$('#root').innerHTML=publicHeader()+`<main id="main" class="auth-layout">${authAside()}<section class="auth-form-wrap" aria-label="${register?'Create account':'Sign in'}"><div class="auth-card${register?' wide':''}"><span class="eyebrow">YOUR LEARNING SPACE</span><h1 class="subhead">${register?'Start your path.':kind==='forgot'?'Recover your account.':'Welcome back.'}</h1><p class="muted">${register?'Create a student account or verify your faculty invitation.':'Sign in to continue where you left off.'}</p><div id="auth-error" role="alert"></div><form id="auth-form" data-kind="${kind}">${kind==='forgot'?field('Email','email','email','required autocomplete="email"')+`<div class="actions"><button type="submit">Send recovery email</button></div><hr><h3 class="subhead">Already have a reset token?</h3>${field('One-time token','token')}${field('New password (12+ characters)','new_password','password','minlength="12"')}<button type="button" class="secondary" data-action="reset-password">Reset with token</button>`:`<div class="${register?'form-grid':''}">${register?field('Full name','name','text','required maxlength="120" autocomplete="name"')+field('University / faculty ID','university_id','text','required maxlength="80"'):''}${field('Email address','email','email','required autocomplete="email"')}${field('Password','password','password',`required ${register?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'}`)}${register?field('Confirm password','confirm_password','password','required minlength="12" autocomplete="new-password"')+`<div><label for="role">Account type</label><select name="role" id="role"><option value="student">Student</option><option value="teacher">Teacher — invite required</option></select></div><div class="span2" id="faculty-key" hidden>${field('Faculty invite code','teacher_key','password','autocomplete="off"')}<p class="footer-note">Get this privately from your administrator. Use email and password for future logins.</p></div>${field('Department','department')}${field('Degree program','program')}${field('Semester','semester')}${field('Campus','campus')}${field('Designation (teachers)','designation')}`:''}</div><div class="actions"><button type="submit">${register?'Create account':'Sign in'} ${icon('arrow')}</button>${!register?'<button type="button" class="ghost" data-action="forgot">Forgot password?</button>':''}</div>`}</form><p class="footer-note">${register?'Already have an account? <a href="/login">Sign in</a>':'New to CampusPath? <a href="/register">Create an account</a>'}</p></div></section></main>`;
}
const studentNav=[['dashboard','home','Overview'],['courses','book','My courses'],['path','path','Learning path'],['tutor','spark','Course tutor'],['quiz','quiz','Practice quiz'],['graph','graph','Knowledge map'],['formal-viva','mic','Assigned viva'],['voice','mic','Practice viva'],['materials','book','Materials'],['assignments','quiz','Assignments'],['planner','calendar','Study & revision'],['lab','code','Algorithm lab (computing)'],['analytics','chart','My results'],['notifications','calendar','Notifications'],['settings','settings','Settings']];
const teacherNav=[['dashboard','home','Overview'],['courses','book','My courses'],['students','people','Students'],['topics','graph','Concepts'],['materials','book','Course materials'],['questions','quiz','Question bank'],['assignments','quiz','Assignments'],['analytics','chart','Class intelligence'],['copilot','spark','Teacher copilot'],['formal-viva','mic','Create viva'],['oral-review','quiz','Viva marks review'],['viva-analytics','chart','Viva analytics'],['viva-review','mic','Practice review'],['structure','graph','Material curriculum'],['research','chart','Research checks'],['notifications','calendar','Notifications'],['settings','settings','Settings']];
function navItems(){return state.user.role==='student'?studentNav:state.user.role==='teacher'?teacherNav:[['dashboard','shield','Administration'],['settings','settings','Settings']];}
/* Primary items follow the real task order; everything else sits under "More learning tools". */
const primaryNav={student:['dashboard','courses','path','quiz','voice','formal-viva','assignments','analytics'],teacher:['dashboard','courses','materials','topics','questions','formal-viva','assignments','oral-review','students']};
function navHint(id){const teacher=state.user?.role==='teacher';const hints={voice:'Practice only. Not an assessed viva.','formal-viva':teacher?'Build, review and publish assessed vivas.':'Assessed by your teacher.'};return hints[id]||'';}
function navButton([id,ic,label]){const hint=navHint(id);return `<button data-nav="${id}"${hint?` title="${e(hint)}"`:''}>${icon(ic)}${label}</button>`;}
function navSplit(){const items=navItems();const order=primaryNav[state.user.role];if(!order)return {primary:items,more:[]};return {primary:order.map(id=>items.find(([x])=>x===id)).filter(Boolean),more:items.filter(([id])=>!order.includes(id))};}
async function shell(signal){state.courses=await api('/courses',{signal});if(!state.courses.some(c=>c.id===state.cid))state.cid=state.courses[0]?.id||null;
 $('#root').innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<div class="nav-label">${e(state.user.role.toUpperCase())} WORKSPACE</div><nav class="nav" id="site-nav" aria-label="Main navigation">${navSplit().primary.map(navButton).join('')}${navSplit().more.length?`<details class="nav-more"><summary>More learning tools <span aria-hidden="true">⌄</span></summary>${navSplit().more.map(navButton).join('')}</details>`:''}</nav><div class="sidebar-foot"><div class="privacy">${icon('shield')} ${state.user.role==='student'?'Only you and your assigned teachers can access your course progress.':'Access is limited to your assigned course sections.'}</div><div class="user-mini"><span class="avatar">${e(state.user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${e(state.user.name)}</strong><small>${e(state.user.university_id)}</small></div></div></div></aside><div class="workarea"><header class="topbar"><div class="actions"><button class="secondary menu-toggle" data-action="menu" aria-label="Open navigation menu" aria-expanded="false" aria-controls="site-nav">${icon('menu')}</button><select id="course-select" aria-label="Active course">${state.courses.length?state.courses.map(c=>`<option value="${c.id}" ${c.id===state.cid?'selected':''}>${e(c.code)} · ${e(c.name)}</option>`).join(''):'<option>No enrolled courses</option>'}</select></div><div class="actions"><span class="tag green" id="workspace-mode">${state.health?.demo_mode?'DEMO ENVIRONMENT':'LEARNING WORKSPACE'}</span><button class="ghost" data-action="theme" aria-label="Switch light or dark theme" title="Switch light or dark theme">${icon('moon')}</button><button class="secondary small" data-action="logout">Sign out</button></div></header><main id="main" class="content"></main></div></div>`;
 await navigate(state.page);
}
function heading(title,desc='',actions=''){return `<div class="page-heading"><div><span class="eyebrow">${e(state.courses.find(c=>c.id===state.cid)?.code||'CAMPUSPATH AI')} / ${e(state.user.role)}</span><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function stat(label,value,caption,ic='chart'){return `<div class="stat"><div class="row"><span class="stat-label">${label}</span>${icon(ic)}</div><strong>${value??'—'}</strong><small>${caption}</small></div>`;}
function empty(title,desc,button=''){return `<div class="empty"><h2>${title}</h2><p>${desc}</p>${button}</div>`;}
function bar(value){return `<div class="progress"><span class="${value<60?'low':''}" style="width:${Math.min(100,Math.max(0,Number(value)))}%"></span></div>`;}
function topicsCard(topics){return `<section class="card"><div class="row"><h2>Concept mastery</h2><span class="tag">MODEL ESTIMATE</span></div>${topics.map(t=>`<div class="topic-row"><div class="row"><button data-topic="${t.id}">${e(t.name)}</button><strong>${t.mastery}%</strong></div>${bar(t.mastery)}<small>${t.attempts} observed attempts · ${Math.round(t.confidence*100)}% evidence confidence</small></div>`).join('')}</section>`;}
function chart(values){const list=Object.entries(values);return list.length?`<div class="chart" role="img" aria-label="${e(list.map(([k,v])=>`${k}: ${v}%`).join(', '))}">${list.map(([k,v])=>`<div class="chart-item"><div class="chart-bar" style="height:${Number(v)}%"><small>${v}%</small></div><label title="${e(k)}">${e(k)}</label></div>`).join('')}</div>`:empty('No assessment evidence','Results appear after assessed activity.');}
async function navigate(page){stopVoice();clearInterval(state.quizTimer);clearInterval(state.oralTimer);state.page=page;$('.sidebar')?.classList.remove('open');$('.menu-toggle')?.setAttribute('aria-expanded','false');document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===page);b.setAttribute('aria-current',b.dataset.nav===page?'page':'false');});const ticket=state.navTicket=(state.navTicket||0)+1;try{await window.CampusTransition?.leave(page);}catch{}if(ticket!==state.navTicket)return;$('#main').classList.remove('pt-leave');$('#main').innerHTML='<div class="loading" role="status" aria-label="Loading page"></div>';
 try{if(!state.cid&&!['courses','settings','notifications'].includes(page)&&state.user.role!=='admin'){page='courses';state.page=page;}
 const renderers={'formal-viva':formalVivaPage,'oral-review':oralReviewPage,'viva-analytics':vivaAnalytics,structure:structureStudio,notifications:notificationPage,'viva-review':vivaReviewPage,research:researchPage,dashboard, courses:coursePage,path:pathPage,tutor:tutorPage,quiz:quizPage,graph:graphPage,voice:voicePage,materials:materialsPage,assignments:assignmentsPage,planner:plannerPage,lab:labPage,analytics:analyticsPage,students:studentsPage,topics:topicsPage,questions:questionsPage,copilot:copilotPage,settings:settingsPage};await renderers[page]();}
 catch(err){if(ticket!==state.navTicket)return;$('#main').innerHTML=heading('Unable to load this page')+`<div class="error-state" role="alert">${e(err.message)}<div class="actions"><button data-action="retry">Try again</button></div></div>`;}
 if(ticket===state.navTicket)window.CampusTransition?.enter(state.page);
}
async function getProgress(sid=state.user.id){return api(`/courses/${state.cid}/students/${sid}/progress`);}
async function dashboard(){if(state.user.role==='admin')return adminPage();if(state.user.role==='teacher')return teacherDashboard();const p=state.progress=await getProgress();
 const next=p.path[0];$('#main').innerHTML=heading(`Your next step, ${e(state.user.name.split(' ')[0])}.`,'A little clarity. A little practice. Meaningful progress.',`<button class="secondary" data-nav="quiz">Start a check-in ${icon('arrow')}</button>`)+`<p class="footer-note" id="demo-progress-note"${state.health?.demo_mode?'':' hidden'}>Demo course and starting mastery values are synthetic. New quiz results are saved from your actual answers.</p><div class="stats">${stat('Overall mastery',p.mastery+'%','Across your course concepts')}${stat('Exam readiness',p.readiness+'%','An indicator, not a grade prediction','shield')}${stat('Quiz accuracy',p.quiz_average===null?'—':p.quiz_average+'%',p.attempts+' answers recorded','quiz')}${stat('Upcoming reviews',p.revisions.length,'Spaced practice keeps learning active','calendar')}</div><div class="next-card"><div><span class="eyebrow">RECOMMENDED NEXT</span><h2>${next?e(next.name):'Keep your knowledge fresh'}</h2><p>${next?e(next.why):'Try a diagnostic to check the full course.'}</p><div class="actions subhead"><button data-nav="path">Open learning path ${icon('arrow')}</button><button class="ghost" data-nav="tutor">Ask the course tutor</button></div></div><div class="orb" aria-hidden="true">${icon('path')}</div></div><div class="grid">${topicsCard(p.topics)}<div><section class="card"><div class="row"><h2>Course outcomes</h2><span class="tag violet">CLO</span></div>${chart(p.clos)}<p class="footer-note">Average estimated mastery for the topics mapped to each outcome.</p></section><section class="card"><h2>Reflect & revise</h2>${p.misconceptions.length?p.misconceptions.slice(0,3).map(m=>`<div class="list-item"><p>${e(m.evidence)}</p></div>`).join(''):'<p class="muted">No misconceptions recorded yet. Your next assessment will help identify what to work on.</p>'}<button class="secondary" data-nav="planner">See revision calendar</button></section></div></div>`;
}
async function teacherDashboard(){const a=await api(`/courses/${state.cid}/analytics`);const c=state.courses.find(c=>c.id===state.cid);$('#main').innerHTML=heading('Make the next lesson count.','A clear view of your class, grounded in learning evidence.',`<button data-nav="students">View students ${icon('arrow')}</button>`)+`<div class="stats">${stat('Enrolled students',a.students,'Section '+e(c.section),'people')}${stat('Class mastery',a.mastery===null?'—':a.mastery+'%','Average topic estimate')}${stat('May need support',a.support_count,'Multiple evidence factors considered','shield')}${stat('Course concepts',a.topics.length,'Editable prerequisite structure','graph')}</div><div class="next-card"><div><span class="eyebrow">COURSE INVITATION</span><h2>${e(c.enrollment_code)}</h2><p>Share this enrollment code with your students. Faculty registration uses a separate private invitation.</p><button class="secondary subhead" data-action="copy-enrollment">Copy enrollment code</button></div>${icon('book')}</div><div class="grid"><section class="card"><h2>Where the class stands</h2>${a.topics.map(t=>`<div class="topic-row"><div class="row"><span>${e(t.name)}</span><strong>${t.mastery??'—'}${t.mastery===null?'':'%'}</strong></div>${bar(t.mastery||0)}</div>`).join('')}</section><section class="card"><h2>CLO attainment estimates</h2>${chart(a.clos)}<p class="footer-note">${e(a.methodology)}</p><button class="secondary" data-nav="copilot">Plan a remedial activity</button></section></div>`;}
async function coursePage(){const teacher=state.user.role==='teacher';$('#main').innerHTML=heading('Your courses.','One connected space for material, practice and progress.')+`<div class="grid equal"><section class="card"><h2>${teacher?'Create a course section':'Join a course'}</h2><form id="${teacher?'course-form':'join-form'}">${teacher?field('Course name','name','text','required')+`<div class="split">${field('Course code','code','text','required')}${field('Section','section','text','required')}</div>${field('Semester','semester')}<label for="description">Description</label><textarea id="description" name="description"></textarea><label for="clos">Course learning outcomes (one per line)</label><textarea id="clos" name="clos" placeholder="CLO-1: Explain core concepts"></textarea>`:field('Enrollment code from your teacher','code','text','required')}<button class="subhead" type="submit">${teacher?'Create course':'Join course'}</button></form></section><section class="card"><h2>${teacher?'Teaching':'Enrolled'} courses</h2>${state.courses.length?state.courses.map(c=>`<div class="list-item"><span class="tag">${e(c.code)} · ${e(c.section)}</span><h3 class="subhead">${e(c.name)}</h3><p>${e(c.description)}</p><button class="secondary" data-course="${c.id}">Open course ${icon('arrow')}</button></div>`).join(''):empty('Your first course starts here',teacher?'Create a section and invite students.':'Ask your teacher for an enrollment code.')}</section></div>`;}
async function pathPage(){const p=state.progress=await getProgress();$('#main').innerHTML=heading('A path with a reason.','Your prerequisite gaps come before dependent concepts.')+`<div class="grid"><section class="card"><h2>Recommended sequence</h2>${p.path.length?p.path.map((t,i)=>`<div class="path-item"><span class="number">${i+1}</span><div><h3>${e(t.name)}</h3><p>${e(t.why)}</p><small>Evidence confidence ${Math.round(t.confidence*100)}%</small><div class="actions subhead"><button class="secondary small" data-topic="${t.id}">Study concept</button><button class="small" data-practice="${t.id}">Practice</button></div></div></div>`).join(''):empty('Ready for a mastery check','Your current model shows no topics below 80%. Take another assessment to check retention.')}</section><section class="card"><h2>Why this order?</h2><p class="muted">CampusPath visits weak prerequisites before the concepts that depend on them. The estimate changes when you submit new assessment evidence.</p><p class="muted">Low confidence means there have been few observed attempts. Treat the estimate as a starting point for discussion.</p><button class="secondary" data-nav="graph">Explore knowledge map</button></section></div>`;}
async function tutorPage(){ $('#main').innerHTML=heading('A tutor connected to your course.','Answers include the excerpts and source locations used.')+`<div class="grid"><section class="card"><div class="row"><h2>What are you working on?</h2>${icon('spark')}</div><form id="tutor-form"><label for="mode">Explanation preference</label><select name="mode" id="mode">${['Simple English','Detailed','Roman Urdu','Step-by-step','Analogy','Worked Example','Code Example','Exam Focus','Socratic Mode'].map(x=>`<option ${state.user.profile?.mode===x?'selected':''}>${x}</option>`).join('')}</select><label for="question">Your question</label><textarea id="question" name="question" required minlength="2" maxlength="4000" placeholder="Explain the main idea of Chapter 2 step by step, with an example."></textarea><button class="subhead" type="submit">Ask course tutor ${icon('arrow')}</button></form><div id="tutor-output" aria-live="polite"></div></section><section class="card"><h2>Grounded in your materials</h2><p class="muted">The tutor searches course resources and your private uploads. It does not see other students’ personal material.</p><div class="alert">${state.health?.demo_mode?'Offline demo: extractive answers and supplied bilingual notes. These are not newly generated LLM explanations.':'If a configured provider fails, you receive labelled source excerpts.'}</div><button class="secondary" data-nav="materials">Manage your materials</button><button class="ghost" data-nav="voice">Open voice practice</button></section></div>`;}
async function quizPage(){return renderQuizSetup();}
function renderQuiz(run){return paintQuiz(run);}
function graphSVG(topics){const cols=3,w=650,h=Math.ceil(topics.length/cols)*135+30;const coords=new Map(topics.map((t,i)=>[t.id,{x:95+(i%cols)*220,y:65+Math.floor(i/cols)*135}]));return `<svg class="graph" viewBox="0 0 ${w} ${h}" role="img" aria-label="Course prerequisite graph. Arrows point from prerequisite to dependent topic."><defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" fill="currentColor"/></marker></defs>${topics.flatMap(t=>(t.prerequisites||[]).filter(p=>coords.has(p)).map(p=>`<line x1="${coords.get(p).x}" y1="${coords.get(p).y+27}" x2="${coords.get(t.id).x}" y2="${coords.get(t.id).y-30}" marker-end="url(#arr)"/>`)).join('')}${topics.map(t=>`<g data-topic="${t.id}" tabindex="0" role="button" aria-label="${e(t.name)} ${t.mastery??'unassessed'} percent" class="${(t.mastery??0)<60?'low':''}"><circle cx="${coords.get(t.id).x}" cy="${coords.get(t.id).y}" r="30"/><text x="${coords.get(t.id).x}" y="${coords.get(t.id).y+5}" text-anchor="middle">${t.mastery??'—'}${t.mastery===undefined?'':'%'}</text><text x="${coords.get(t.id).x}" y="${coords.get(t.id).y+53}" text-anchor="middle">${e(t.name)}</text></g>`).join('')}</svg>`;}
async function graphPage(){const p=state.progress=await getProgress();$('#main').innerHTML=heading('See how your knowledge connects.','Select a concept to inspect its prerequisites and learning material.')+`<section class="card">${graphSVG(p.topics)}<div class="row"><span class="tag green">60%+ estimated mastery</span><span class="tag warn">Below 60% · needs practice</span><small>Low evidence confidence? Start with a diagnostic.</small></div></section>`;}
async function showTopic(id){const topics=state.user.role==='student'?(state.progress?.topics||((state.progress=await getProgress()).topics)):await api(`/courses/${state.cid}/topics`);const t=topics.find(t=>t.id===id);if(!t)return;modal(`<span class="eyebrow">${e(t.clo)}</span><h1 class="subhead">${e(t.name)}</h1><p>${e(t.description)}</p><h3>Prerequisites</h3><p>${t.prerequisites.length?t.prerequisites.map(id=>e(topics.find(p=>p.id===id)?.name||id)).join(', '):'No prerequisites defined.'}</p>${t.mastery!==undefined?`<p>Estimated mastery: <strong>${t.mastery}%</strong> · ${t.attempts} observed attempts</p><button data-practice="${t.id}">Practice this concept</button>`:''}`);}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
async function materialsPage(){const rows=await api(`/courses/${state.cid}/resources`);$('#main').innerHTML=heading('Bring your course into focus.','Source locations stay attached to every indexed excerpt.')+`<div class="grid"><section class="card"><h2>${state.user.role==='student'?'Your accessible resources':'Course material manager'}</h2>${rows.length?rows.map(r=>`<div class="list-item"><div class="row"><h3>${e(r.filename)}</h3><span class="tag ${r.kind==='PERSONAL MATERIAL'?'violet':'green'}">${e(r.kind)}</span></div>${r.status==='processing'?'<p class="alert">Reading this document in the background… refresh in a minute.</p>':r.status==='failed'?`<p class="alert">Could not index: ${e(r.status_detail||'unknown error')}</p>`:''}<button class="secondary small" data-resource="${r.id}">Read indexed content</button> ${r.download_available?`<a href="/api/courses/${state.cid}/resources/${r.id}/download">Download original</a>`:''}</div>`).join(''):empty('No resources yet','Upload a lecture or some notes to begin.')}</section><section class="card"><h2>Index a resource</h2><form id="upload-form"><label for="file">Document (up to ${state.health?.max_upload_mib||8} MiB)</label><input class="file-input" id="file" name="file" type="file" required accept=".pdf,.docx,.pptx,.txt,.md,.csv,.py,.cpp,.c,.java,.js,.html,.css,.json,.png,.jpg,.jpeg,.webp,.mp3,.wav,.m4a,.ogg,.mp4"><p class="footer-note">PDF, PowerPoint, Word, UTF-8 text and code. Uploaded code is treated as text and never executed. Images use optional Tesseract OCR. Audio requires a speech provider; video additionally requires FFmpeg and is limited to five minutes. Verify extracted text before relying on it.</p><button type="submit">Upload & index</button></form><div class="alert">${state.user.role==='student'?'Your uploads stay private unless you attach one to an assignment for teacher review.':'Course material becomes available to students enrolled in this section.'}</div><form id="search-form"><label for="search">Search this course</label><input id="search" name="q" minlength="2" required><button class="secondary subhead" type="submit">Search sources</button></form><div id="search-output"></div></section></div>`;}
async function assignmentsPage(){return renderAssignments();}
async function plannerPage(){return renderPlanner();}
async function labPage(){state.algorithm=await api('/algorithm/A*');state.step=0;$('#main').innerHTML=heading('Watch the search unfold.','A deterministic, weighted graph. One decision at a time.')+`<div class="grid"><section class="card"><label for="algorithm">Search algorithm</label><select id="algorithm"><option>A*</option><option>BFS</option><option>DFS</option><option>UCS</option></select><div id="lab-graph"></div><div class="actions"><button class="secondary" data-action="lab-prev">Previous</button><button data-action="lab-next">Next step ${icon('arrow')}</button><button class="ghost" data-action="lab-reset">Reset</button></div></section><section class="card" id="lab-state"></section></div>`;renderLab();}
function renderLab(){const s=state.algorithm.steps[state.step],coords={S:[60,150],A:[220,60],B:[220,250],C:[390,60],D:[390,250],G:[550,150]};$('#lab-graph').innerHTML=`<svg class="graph" viewBox="0 0 620 340" aria-label="Weighted search graph"><defs><marker id="lab-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 10 5 0 10z" fill="currentColor"/></marker></defs>${Object.entries(state.algorithm.graph).flatMap(([n,edges])=>edges.map(([m,c])=>`<line x1="${coords[n][0]+22}" y1="${coords[n][1]}" x2="${coords[m][0]-27}" y2="${coords[m][1]}" marker-end="url(#lab-arrow)"/><text x="${(coords[n][0]+coords[m][0])/2}" y="${(coords[n][1]+coords[m][1])/2-7}">${c}</text>`)).join('')}${Object.entries(coords).map(([n,[x,y]])=>`<g><circle cx="${x}" cy="${y}" r="24" style="${n===s.current?'fill:var(--accent);':s.visited.includes(n)?'stroke:var(--violet);':''}"/><text x="${x}" y="${y+5}" text-anchor="middle" style="${n===s.current?'fill:var(--bg)':''}">${n}</text></g>`).join('')}</svg>`;$('#lab-state').innerHTML=`<span class="eyebrow">STEP ${state.step+1} / ${state.algorithm.steps.length}</span><h2 class="subhead">Expand ${e(s.current)}</h2><div class="code">g(n) = ${s.g}\nh(n) = ${s.h}\nf(n) = ${s.f}</div><h3 class="subhead">Frontier</h3><p>${e(s.frontier.join(' → ')||'Empty')}</p><h3>Visited</h3><p>${e(s.visited.join(', '))}</p><h3>Current path</h3><p>${e(s.path.join(' → '))}</p><div class="alert">${e(s.explanation)}</div><p class="footer-note">${state.algorithm.algorithm==='DFS'?'DFS removes from the end of the shown frontier.':state.algorithm.algorithm==='BFS'?'BFS removes from the beginning of the shown frontier.':'Frontier is ordered by search priority.'} This is a fixed teaching graph, not a graph editor.</p>`;}
async function analyticsPage(){const teacher=state.user.role==='teacher';if(teacher){const a=await api(`/courses/${state.cid}/analytics`);$('#main').innerHTML=heading('Learning evidence, in context.','Class insights are limited to this course section.',`<a href="/api/courses/${state.cid}/report.csv" class="chip" style="padding:10px">Export CSV</a>`)+`<div class="grid equal"><section class="card"><h2>CLO mastery estimates</h2>${chart(a.clos)}</section><section class="card"><h2>Bloom assessment accuracy</h2>${chart(a.bloom)}</section></div><section class="card"><h2>Observed possible misconceptions</h2>${a.misconceptions.length?a.misconceptions.map(m=>`<p class="alert">${e(m.evidence)}</p>`).join(''):'<p class="muted">No misconception evidence recorded yet.</p>'}<p class="footer-note">${e(a.methodology)}</p></section>`;}else{const p=state.progress=await getProgress();$('#main').innerHTML=heading('Your progress, explained.','Every number has a source and a limit.')+`<div class="stats">${stat('Mastery',p.mastery+'%','Bayesian estimate')}${stat('Readiness',p.readiness+'%','Not a predicted exam grade')}${stat('Answers recorded',p.attempts,'Real assessment observations')}${stat('Recent update average',p.trend===null?'—':(p.trend>0?'+':'')+p.trend+' pp','Mean posterior change per recent answer')}</div><div class="grid">${topicsCard(p.topics)}<section class="card"><h2>What makes up readiness?</h2>${readinessCard(p)}<h2 class="subhead">CLO mastery</h2>${chart(p.clos)}</section></div>`;}}
async function studentsPage(){const rows=await api(`/courses/${state.cid}/students`);state.students=rows;$('#main').innerHTML=heading('Know who needs the next step.','Search by name, university ID or email.')+`<section class="card"><div class="split"><label>Find a student<input id="student-search" placeholder="Name or university ID"></label><label>Support status<select id="student-filter"><option value="">All learners</option><option>NEEDS SUPPORT</option><option>DEVELOPING</option><option>PROFICIENT</option><option>HIGH PERFORMING</option></select></label></div><label>Sort by<select id="student-sort"><option value="name">Name</option><option value="mastery">Mastery (highest first)</option><option value="readiness">Readiness (highest first)</option><option value="viva_average">Viva average (highest first)</option></select></label><div id="student-table" class="table-wrap subhead"></div></section>`;renderStudents();}
function renderStudents(){const q=$('#student-search').value.toLowerCase(),filter=$('#student-filter').value,sort=$('#student-sort').value;const rows=state.students.filter(s=>(s.name+' '+s.university_id+' '+s.email).toLowerCase().includes(q)&&(!filter||s.status===filter)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):b[sort]-a[sort]);$('#student-table').innerHTML=`<table><thead><tr><th>Student</th><th>University ID</th><th>Section</th><th>Mastery</th><th>Quiz avg.</th><th>Assignments</th><th>Viva</th><th>Readiness</th><th>Weakest topic</th><th>Support status</th><th>Profile</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${e(s.name)}</td><td>${e(s.university_id)}</td><td>${e(s.section)}</td><td>${s.mastery}%</td><td>${s.quiz_average??'—'}</td><td>${s.assignment_average??'—'}</td><td>${s.viva_average??'—'}</td><td>${s.readiness}%</td><td>${e(s.weakest_topic)}</td><td><span class="tag">${e(s.status)}</span></td><td><button class="secondary small" data-student="${s.id}">View</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class="muted">No matching students.</p>'}`;}
async function studentProfile(id){const [p,notes]=await Promise.all([getProgress(id),api(`/courses/${state.cid}/students/${id}/notes`)]),s=state.students.find(s=>s.id===id);modal(`<span class="eyebrow">STUDENT INTELLIGENCE PROFILE</span><h1 class="subhead">${e(s.name)}</h1><p>${e(s.university_id)} · Section ${e(s.section)}</p><div class="stats">${stat('Mastery',p.mastery+'%','Model estimate')}${stat('Readiness',p.readiness+'%','Learning indicator')}${stat('Viva',p.viva_average===null?'—':p.viva_average+'%',p.viva_reviewed_count+' teacher-reviewed responses')}${stat('Study streak',p.study_streak+' days',p.revision_completion.done+' revisions completed')}</div>${topicsCard(p.topics)}<h2>Readiness factors</h2>${readinessCard(p)}<h2>Bloom accuracy</h2>${chart(p.bloom)}<h2>Possible misconceptions</h2>${p.misconceptions.map(m=>`<p>${e(m.evidence)}</p>`).join('')||'<p class="muted">No evidence yet.</p>'}<h2>Private teacher notes</h2>${notes.map(n=>`<p class="alert">${e(n.text)}</p>`).join('')}<form id="note-form" data-id="${id}"><label>New note<textarea name="text" required></textarea></label><button type="submit">Save private note</button></form>`);}
async function topicsPage(){state.topics=await api(`/courses/${state.cid}/topics`);$('#main').innerHTML=heading('The structure behind the learning.','Review and edit topics, prerequisite links and course outcomes.','<button class="secondary" data-action="generate-curriculum">Generate draft</button><button data-action="new-topic">Add concept</button>')+`<div class="grid"><section class="card">${state.topics.length?graphSVG(state.topics):empty('Start with the syllabus','Add concepts, then connect their prerequisites.')}</section><section class="card"><h2>Course concept editor</h2><p class="footer-note">Edit the structure manually or generate a draft with a configured LLM. Teacher review is required. Circular prerequisites are rejected.</p>${state.topics.map(t=>`<div class="list-item"><div class="row"><div><h3>${e(t.name)}</h3><small>${e(t.clo)}</small></div><button class="secondary small" data-edit-topic="${t.id}">Edit</button></div></div>`).join('')}</section></div>`;}
function topicForm(id){const t=state.topics.find(t=>t.id===id)||{};modal(`<h2>${id?'Edit':'Add'} course concept</h2><form id="topic-form" data-id="${id||''}">${field('Topic name','name','text','required',t.name||'')}<label>Description<textarea name="description">${e(t.description||'')}</textarea></label>${field('CLO','clo','text','required',t.clo||'CLO-1')}${field('Difficulty (1–3)','difficulty','number','required min="1" max="3"',t.difficulty||1)}<label>Prerequisite topic IDs, comma-separated<input name="prerequisites" value="${e((t.prerequisites||[]).join(','))}"></label><p class="footer-note">${state.topics.filter(x=>x.id!==id).map(x=>`${x.id}: ${e(x.name)}`).join(' · ')||'No other topics yet.'}</p><button type="submit">Save concept</button></form>`);}
async function questionsPage(){const [questions,topics]=await Promise.all([api(`/courses/${state.cid}/questions`),api(`/courses/${state.cid}/topics`)]);state.topics=topics;state.questions=questions;$('#main').innerHTML=heading('Good questions make good evidence.','Review the answer, explanation, difficulty and source before publishing.','<button class="secondary" data-action="generate-question">Generate question batch</button><button data-action="new-question">Write question</button>')+`<section class="card"><div class="alert">Drafts can be authored by you or a configured LLM. Automated checks validate structure, source and duplicates; you must review correctness and ambiguity before approval.</div>${questions.map(q=>`<div class="list-item"><div class="row"><span class="tag ${q.approved?'green':'violet'}">${q.approved?'APPROVED':'DRAFT / REJECTED'}</span><small>${e(q.bloom)} · Difficulty ${q.difficulty}</small></div><h3 class="subhead">${e(q.prompt)}</h3><p>Answer: ${e(q.options[q.correct])}</p><p>${e(q.explanation)}</p><small>${e(q.source)}</small><div class="actions subhead"><button class="secondary small" data-review="${q.id}" data-decision="${q.approved?'reject':'approve'}">${q.approved?'Unpublish':'Approve'}</button><button class="ghost small" data-edit-question="${q.id}">Edit draft</button></div></div>`).join('')||empty('No questions yet','Write a question, verify its answer and approve it.')}</section>`;}
function questionForm(id,draft){const q=draft||state.questions.find(q=>q.id===id)||{};modal(`<h2>${id?'Edit':'Write'} assessment question</h2><form id="question-form" data-id="${id||''}"><label>Topic<select name="topic_id" required>${state.topics.map(t=>`<option value="${t.id}" ${q.topic_id===t.id?'selected':''}>${e(t.name)}</option>`).join('')}</select></label><label>Question<textarea name="prompt" required minlength="8">${e(q.prompt||'')}</textarea></label><label>Options (one per line, 2–6)<textarea name="options" required>${e((q.options||[]).join('\n'))}</textarea></label>${field('Correct option number (1–6)','correct','number','required min="1" max="6"',(q.correct??0)+1)}<label>Explanation<textarea name="explanation" required>${e(q.explanation||'')}</textarea></label>${field('Possible misconception','misconception','text','',q.misconception||'')}${field('Difficulty','difficulty','number','min="1" max="3" required',q.difficulty||1)}<label>Bloom level<select name="bloom">${['Remember','Understand','Apply','Analyze','Evaluate','Create'].map(x=>`<option ${q.bloom===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Source','source','text','required',q.source||'Teacher authored')}${field('Teacher source chunk IDs (comma separated)','source_ids','text','',(q?.source_ids||[]).join(','))}<button type="submit">Save draft for review</button></form>`);}
async function copilotPage(){$('#main').innerHTML=heading('Turn evidence into teaching action.','Responses use only learners enrolled in this course.')+`<section class="card"><form id="copilot-form"><label>What should we look at?<textarea name="text" required placeholder="Which students need help with our weakest concept? Generate a 15-minute activity."></textarea></label><button type="submit">Inspect course evidence</button></form><div id="copilot-output" aria-live="polite"></div></section>`;}
async function voicePage(){return renderVoice();}
function stopVoice(){stopStreamMic();if(state.voiceSocket){state.voiceSocket.close();state.voiceSocket=null;}state.voiceEpoch=(state.voiceEpoch||0)+1;if(state.audioUrl){URL.revokeObjectURL(state.audioUrl);state.audioUrl=null;}if(state.recorder&&state.recorder.state!=='inactive'){state.discardRecording=true;state.recorder.stop();}if(state.audio){state.audio.pause();state.audio=null;}if(state.recordTimer)clearTimeout(state.recordTimer);if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null;}if(state.recognition){state.recognition.onend=null;state.recognition.stop();state.recognition=null;}if('speechSynthesis' in window)speechSynthesis.cancel();$('#voice-orb')?.classList.remove('listening');if($('#voice-status'))$('#voice-status').textContent='Ready · microphone off';}
function speak(text){if(state.health?.tts_configured){speakServer(text);return;}stopVoice();if(!('speechSynthesis'in window)){toast('Speech playback is unavailable. Read the on-screen text.');return;}const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.onend=()=>{if($('#voice-status'))$('#voice-status').textContent='Ready · microphone off';};u.onerror=()=>toast('Playback unavailable. Use the visible text.');if($('#voice-status'))$('#voice-status').textContent='Speaking · microphone off';speechSynthesis.speak(u);}
function record(){if(state.health?.stt_configured){if(window.WebSocket&&(window.AudioContext||window.webkitAudioContext))recordWebSocket();else recordServer();return;}stopVoice();const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Speech recognition is unavailable in this browser. Type your answer instead.');return;}const r=state.recognition=new Recognition();r.lang='en-US';r.interimResults=true;r.continuous=false;r.onresult=event=>{if(!$('#transcript'))return;$('#transcript').value=Array.from(event.results).map(x=>x[0].transcript).join(' ');};r.onerror=event=>{toast('Microphone: '+event.error+'. You can type your answer.');stopVoice();};r.onend=()=>{state.recognition=null;$('#voice-orb')?.classList.remove('listening');if($('#voice-status'))$('#voice-status').textContent='Review your transcript, then submit.';};try{r.start();$('#voice-status').textContent='Listening…';$('#voice-orb').classList.add('listening');}catch{stopVoice();toast('Unable to start microphone. Type your answer.');}}
async function settingsPage(){return renderSettings();}
async function adminPage(){const a=await api('/admin/overview');$('#main').innerHTML=heading('Administration.','Faculty verification and audit visibility.')+`<div class="stats">${stat('Accounts',a.users.length,'Registered users','people')}${stat('Faculty invitations',a.keys.length,'Secrets never returned by the API','shield')}</div><section class="card"><h2>Faculty invitations</h2><p class="muted">Invite a teacher from any department. The code is shown once: send it privately (WhatsApp, email). The teacher chooses <strong>Teacher</strong> on the registration page and pastes it.</p><form id="invite-form" class="form-grid"><div><label for="invite-password">Your admin password</label><input id="invite-password" name="password" type="password" required autocomplete="current-password"></div><div class="split"><div><label for="invite-days">Valid for (days)</label><input id="invite-days" name="days" type="number" min="1" max="90" value="7" required></div><div><label for="invite-uses">Teachers who can use it</label><input id="invite-uses" name="uses" type="number" min="1" max="100" value="1" required></div></div><div class="actions"><button type="submit">Create faculty invitation 🔑</button></div></form><div id="invite-output" aria-live="polite"></div><p class="footer-note">Command-line alternative: <code>python scripts/manage.py invite --admin-email …</code>. Revoke an invite below to rotate it.</p>${a.keys.map(k=>`<div class="list-item row"><span>Invite #${k.id} · ${k.uses}/${k.limit} used · ${k.revoked?'Revoked':'Expires '+new Date(k.expires+'Z').toLocaleDateString()}</span>${!k.revoked?`<button class="secondary small" data-revoke="${k.id}">Revoke</button>`:''}</div>`).join('')}</section><section class="card"><h2>Registered users</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>University ID</th><th>Role</th><th>Account</th></tr></thead><tbody>${a.users.map(u=>`<tr><td>${e(u.name)}</td><td>${e(u.university_id)}</td><td>${e(u.role)}</td><td>${u.role!=='admin'?`<button class="secondary small" data-account-state="${u.id}" data-active="${!u.active}">${u.active?'Suspend':'Enable'}</button>`:'Administrator'}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Recent audit events</h2>${a.audit.map(v=>`<div class="list-item"><strong>${e(v.action)}</strong> · Actor ${v.actor_id} · ${e(v.target)}<br><small>${new Date(v.created+'Z').toLocaleString()}</small></div>`).join('')}</section>`;await adminExtras();}
function sourceCards(sources){return sources.map(s=>`<details class="source"><summary>${e(s.filename)} · ${e(s.location)}${s.id?` · Chunk #${s.id}`:''}</summary><p>${e(s.text)}</p></details>`).join('');}
async function login(email,password){const r=await post('/auth/login',{email,password});state.user=r.user;state.csrf=r.csrf;state.progress=null;state.students=[];state.quiz=null;state.page='dashboard';state.cid=null;await shell();}
document.addEventListener('submit',async event=>{const form=event.target;event.preventDefault();const b=form.querySelector('button[type="submit"]')||form.querySelector('button');if(b)b.disabled=true;const data=Object.fromEntries(new FormData(form));try{
 if(await workflowSubmit(form,data))return;
 if(form.id==='auth-form'){
  if(form.dataset.kind==='register'){await post('/auth/register',data);toast('Account created. You can sign in now.');authPage('login');}
  else if(form.dataset.kind==='forgot'){const result=await post('/auth/forgot',{email:data.email});toast(result.message);}
  else await login(data.email,data.password);
 }else if(form.id==='invite-form'){const r=await post('/admin/keys',{password:data.password,days:Number(data.days),uses:Number(data.uses)});form.reset();$('#invite-output').innerHTML=`<div class="alert"><strong>Faculty invitation (shown only once)</strong><p class="code" style="user-select:all;word-break:break-all">${e(r.token)}</p><small>Valid until ${new Date(r.expires+(r.expires.endsWith('Z')?'':'Z')).toLocaleDateString()} · ${r.limit} use(s)</small><div class="actions"><button type="button" class="secondary small" data-copy-invite="${e(r.token)}">Copy code</button></div></div>`;toast('Faculty invitation created.');}else if(form.id==='course-form'){data.clos=data.clos.split('\n').map(x=>x.trim()).filter(Boolean);await post('/courses',data);toast('Course created.');await shell();}
 else if(form.id==='join-form'){await post('/courses/join',data);toast('You joined the course.');await shell();}
 else if(form.id==='tutor-form'){$('#tutor-output').innerHTML='<div class="loading subhead" role="status" aria-label="Searching course materials"></div>';try{const result=await post(`/courses/${state.cid}/tutor`,data);$('#tutor-output').innerHTML=`<div class="alert">${e(result.provider_status)}</div><div class="chat-answer">${e(result.answer)}</div>${sourceCards(result.sources)}`;}catch(err){$('#tutor-output').innerHTML=`<div class="alert error">${e(err.message)}</div>`;}}
 else if(form.id==='quiz-form'){data.count=Number(data.count);data.minutes=Number(data.minutes);data.topic_id=data.topic_id?Number(data.topic_id):null;renderQuiz(await post(`/courses/${state.cid}/quiz`,data));}
 else if(form.id==='upload-form'){const result=await api(`/courses/${state.cid}/resources`,{method:'POST',body:new FormData(form)});toast(result.status==='processing'?result.message:`${result.chunks} source excerpts indexed. ${result.vector_status}`);await materialsPage();}
 else if(form.id==='search-form'){const result=await api(`/courses/${state.cid}/search?q=${encodeURIComponent(data.q)}`);$('#search-output').innerHTML=`<div class="subhead">${result.topics.map(t=>`<button class="ghost" data-topic="${t.id}">${e(t.name)}</button>`).join('')}${sourceCards(result.resources)}${!result.resources.length&&!result.topics.length?'<p>No matching evidence found.</p>':''}</div>`;}
 else if(form.classList.contains('submission-form')){await post(`/assignments/${form.dataset.id}/submit`,data);toast('Submission saved.');await assignmentsPage();}
 else if(form.classList.contains('grade-form')){data.grade=Number(data.grade);await post(`/submissions/${form.dataset.id}/grade`,data);toast('Grade saved.');await assignmentsPage();}
 else if(form.id==='assignment-form'){data.source_ids=(data.source_ids||'').split(',').map(x=>x.trim()).filter(Boolean).map(Number);data.due=new Date(data.due).toISOString();await post(`/courses/${state.cid}/assignments`,data);$('#modal').close();toast('Assignment created.');await assignmentsPage();}
 else if(form.id==='plan-form'){data.hours=Number(data.hours);data.exam_date=new Date(data.exam_date+'T12:00:00').toISOString();data.free_days=data.free_days.split(',').map(Number);const r=await post(`/courses/${state.cid}/planner`,data);$('#plan-output').innerHTML=`<div class="alert">${e(r.message)}</div>${r.days.map(d=>`<div class="list-item"><h3>${e(d.date)}</h3>${d.activities.map(a=>`<p><strong>${e(a.topic)}</strong> · ${a.minutes} minutes<br><small>${e(a.why)}</small></p>`).join('')}</div>`).join('')}`;}
 else if(form.id==='note-form'){await post(`/courses/${state.cid}/students/${form.dataset.id}/notes`,data);toast('Private note saved.');$('#modal').close();}
 else if(form.id==='topic-form'){data.difficulty=Number(data.difficulty);data.prerequisites=data.prerequisites.trim()?data.prerequisites.split(',').map(Number):[];await api(`/courses/${state.cid}/topics${form.dataset.id?'/'+form.dataset.id:''}`,{method:form.dataset.id?'PUT':'POST',body:data});$('#modal').close();toast('Concept saved.');await topicsPage();}
 else if(form.id==='curriculum-form'){const draft=JSON.parse(data.draft);await post(`/courses/${state.cid}/curriculum/approve`,draft);$('#modal').close();toast('Reviewed curriculum saved.');await topicsPage();}
 else if(form.id==='generation-form' && Number(data.count)>1){const r=await post(`/courses/${state.cid}/questions/generate-batch`,{topic_id:Number(data.topic_id),count:Number(data.count)});$('#modal').close();toast(`${r.created} drafts saved. Review each before approval.`);await questionsPage();}
 else if(form.id==='generation-form'){const r=await post(`/courses/${state.cid}/questions/generate`,{topic_id:Number(data.topic_id)});questionForm(null,r.draft);$('#modal-body').insertAdjacentHTML('beforeend',`<div class="alert">${e(r.limitation)}</div>${sourceCards(r.sources)}`);}
 else if(form.id==='question-form'){data.topic_id=Number(data.topic_id);data.correct=Number(data.correct)-1;data.difficulty=Number(data.difficulty);data.source_ids=(data.source_ids||'').split(',').map(x=>x.trim()).filter(Boolean).map(Number);data.options=data.options.split('\n').map(x=>x.trim()).filter(Boolean);await api(`/courses/${state.cid}/questions${form.dataset.id?'/'+form.dataset.id:''}`,{method:form.dataset.id?'PUT':'POST',body:data});$('#modal').close();toast('Draft saved. Review before approval.');await questionsPage();}
 else if(form.id==='copilot-form'){const r=await post(`/courses/${state.cid}/copilot`,data);$('#copilot-output').innerHTML=`<div class="alert">${e(r.status)}</div><h2 class="subhead">${e(r.answer)}</h2>${r.students.map(s=>`<div class="list-item"><strong>${e(s.name)} · ${e(s.university_id)}</strong><p>${s.evidence.map(e).join('<br>')}</p></div>`).join('')}<h2 class="subhead">Remedial activity</h2><p>${e(r.activity)}</p>`;}
 else if(form.id==='viva-form'){stopVoice();const r=await post(`/courses/${state.cid}/viva`,data);state.voiceFeedback=r.feedback;$('#viva-output').innerHTML=`<div class="alert">${e(r.status)}</div><p>${e(r.feedback)}</p><p><strong>Reflect next:</strong> ${e(r.follow_up)}</p><button class="secondary" type="button" data-action="repeat-feedback">Hear feedback</button>`;}
 }catch(err){if($('#auth-error'))$('#auth-error').innerHTML=`<div class="alert error">${e(err.message)}</div>`;else toast(err.message);}finally{if(b&&b.isConnected)b.disabled=false;}});
document.addEventListener('click',async event=>{const copyInvite=event.target.closest&&event.target.closest('[data-copy-invite]');if(copyInvite){try{await navigator.clipboard.writeText(copyInvite.dataset.copyInvite);toast('Invitation copied.');}catch{toast('Select the code and copy it manually.');}return;}const b=event.target.closest('button,[data-topic],a[data-action]');if(!b)return;try{
 if(await workflowClick(b))return;
 if(b.dataset.nav){if($('#modal').open)$('#modal').close();await navigate(b.dataset.nav);return;}
 if(b.dataset.course){state.cid=Number(b.dataset.course);state.progress=null;state.page='dashboard';await shell();return;}
 if(b.dataset.topic){await showTopic(Number(b.dataset.topic));return;}
 if(b.dataset.practice){$('#modal').close();state.page='quiz';renderQuiz(await post(`/courses/${state.cid}/quiz`,{mode:'adaptive',topic_id:Number(b.dataset.practice),count:8,minutes:20}));return;}
 if(b.dataset.answer!==undefined){document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);try{const r=await post(`/quiz/${state.quiz.id}/answer`,{question_id:state.quiz.question.id,selected:Number(b.dataset.answer)});state.quiz=r.next;state.progress=null;window.CampusMascot?.react(r.correct?'cheer':'sad');$('#quiz-feedback').innerHTML=`<div class="alert ${r.correct?'':'error'}"><strong>${r.correct?'Correct.':'Let’s work through it.'}</strong><p class="teaching-feedback">${e(r.explanation)}</p>${r.possible_misconception?`<p>Possible misconception: ${e(r.possible_misconception)}</p>`:''}<p>Estimated mastery: ${r.mastery.before}% → ${r.mastery.after}%</p></div><button data-action="quiz-next">${r.next.complete?'See summary':'Next question'} ${icon('arrow')}</button>`;}catch(err){document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=false);throw err;}return;}
 if(b.dataset.resource){const r=await api(`/courses/${state.cid}/resources/${b.dataset.resource}`);modal(`<h2>${e(r.filename)}</h2>${r.chunks.map(c=>`<details class="source"><summary>Chunk #${c.id} · ${e(c.location)}</summary><p>${e(c.text)}</p></details>`).join('')}`);return;}
 if(b.dataset.revision){await post(`/revisions/${b.dataset.revision}/complete`);toast('Review marked complete.');await plannerPage();return;}
 if(b.dataset.student){await studentProfile(Number(b.dataset.student));return;}
 if(b.dataset.editTopic){topicForm(Number(b.dataset.editTopic));return;}
 if(b.dataset.editQuestion){questionForm(Number(b.dataset.editQuestion));return;}
 if(b.dataset.review){await post(`/courses/${state.cid}/questions/${b.dataset.review}/${b.dataset.decision}`);toast('Review saved.');await questionsPage();return;}
 if(b.dataset.revoke){await post(`/admin/keys/${b.dataset.revoke}/revoke`);toast('Faculty invitation revoked.');await adminPage();return;}
 switch(b.dataset.action){
 case 'login':authPage('login');break;case 'register':authPage('register');break;case 'forgot':authPage('forgot');break;
 case 'theme':{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('campuspath-theme',theme);}catch{}break;}
 case 'demo-student':case 'demo-teacher':
 await healthReady;
 if(!state.health?.demo_mode)throw new Error('Demo accounts are disabled or the server is unavailable.');
 await login(b.dataset.action==='demo-student'?'saim@campuspath.demo':'teacher@campuspath.demo','CampusPath-Demo!2026');break;
 case 'logout':await post('/auth/logout');clearInterval(state.quizTimer);clearInterval(state.oralTimer);stopVoice();state.user=null;state.oralAutoListen=false;state.csrf='';state.progress=null;state.students=[];state.quiz=null;landing();break;
 case 'menu':{const panel=$('.sidebar');const open=panel.classList.toggle('open');b.setAttribute('aria-expanded',String(open));if(open)panel.querySelector('.nav button')?.focus({preventScroll:true});break;}
 case 'close-modal':$('#modal').close();break;
 case 'retry':await navigate(state.page);break;
 case 'copy-enrollment':{const code=state.courses.find(c=>c.id===state.cid).enrollment_code;try{await navigator.clipboard.writeText(code);toast('Enrollment code copied.');}catch{modal(`<h2>Enrollment code</h2><p class="code">${e(code)}</p><p>Select and copy this code.</p>`);}break;}
 case 'quiz-next':renderQuiz(state.quiz);break;
 case 'generate-curriculum':{b.disabled=true;try{const r=await post(`/courses/${state.cid}/curriculum/draft`);modal(`<h2>Review course structure</h2><p>Edit topic names, prerequisites and descriptions before approving.</p><form id="curriculum-form"><label>Draft JSON<textarea name="draft" rows="18" required>${e(JSON.stringify(r.draft,null,2))}</textarea></label><button type="submit">Approve reviewed structure</button></form>`);}finally{b.disabled=false;}break;}
 case 'generate-question':if(!state.topics.length)throw new Error('Create a topic first.');modal(`<h2>Build a balanced question bank</h2><form id="generation-form"><label>Topic<select name="topic_id">${state.topics.map(t=>`<option value="${t.id}">${e(t.name)}</option>`).join('')}</select></label><label>Questions<input name="count" type="number" min="4" max="20" value="10" required></label><p>Creates varied, source-grounded drafts across this topic. Review and approve each draft before student use. Course excerpts are sent to your configured provider.</p><button type="submit">Generate draft</button></form>`);break;
 case 'new-topic':topicForm();break;
 case 'new-question':if(!state.topics.length)throw new Error('Create a course topic first.');questionForm();break;
 case 'new-assignment':modal(`<h2>Create assignment</h2><form id="assignment-form">${field('Title','title','text','required')}<label>Instructions<textarea name="instructions" required></textarea></label><label>Rubric<textarea name="rubric" required></textarea></label>${field('Deadline (your local time)','due','datetime-local','required')}${field('Supporting teacher source chunk IDs (comma separated)','source_ids')}<button type="submit">Create assignment</button></form>`);break;
 case 'lab-next':state.step=Math.min(state.step+1,state.algorithm.steps.length-1);renderLab();break;
 case 'lab-prev':state.step=Math.max(0,state.step-1);renderLab();break;
 case 'lab-reset':state.step=0;renderLab();break;
 case 'record':record();break;case 'finish-record':if(state.recognition)state.recognition.stop();if(state.recorder&&state.recorder.state!=='inactive')state.recorder.stop();break;case 'stop-voice':stopVoice();break;
 case 'speak-question':speak('What does h of n represent?');break;
 case 'repeat-feedback':speak(state.voiceFeedback||'No feedback yet.');break;
 case 'reset-password':{const token=$('#token').value,password=$('#new_password').value;const r=await post('/auth/reset',{token,password});toast(r.message);authPage('login');break;}
 }
 }catch(err){toast(err.message);}});
document.addEventListener('change',async event=>{try{if(event.target.id==='role')$('#faculty-key').hidden=event.target.value!=='teacher';if(event.target.id==='course-select'){state.cid=Number(event.target.value);state.progress=null;await navigate(state.page);}if(event.target.id==='algorithm'){state.algorithm=await api('/algorithm/'+encodeURIComponent(event.target.value));state.step=0;renderLab();}if(['student-filter','student-sort'].includes(event.target.id))renderStudents();}catch(err){toast(err.message);}});
document.addEventListener('input',event=>{if(event.target.id==='student-search')renderStudents();});
document.addEventListener('keydown',event=>{if(event.target.matches('g[data-topic]')&&['Enter',' '].includes(event.key)){event.preventDefault();showTopic(Number(event.target.dataset.topic));}});
window.addEventListener('pagehide',stopVoice);
const healthReady=api('/health',{signal:AbortSignal.timeout(5000)}).then(result=>{
 state.health=result;
 const badge=$('#workspace-mode');
 if(badge)badge.textContent=result.demo_mode?'DEMO ENVIRONMENT':'LEARNING WORKSPACE';
 const note=$('#demo-progress-note');
 if(note)note.hidden=!result.demo_mode;
},()=>{});
async function start(){
 try{document.documentElement.dataset.theme=localStorage.getItem('campuspath-theme')||'light';}catch{}
 try{
  const session=await api('/auth/session',{signal:AbortSignal.timeout(5000)});
  if(session.user){
   state.user=session.user;
   state.csrf=session.csrf;
   await shell(AbortSignal.timeout(5000));
   return;
  }
 }catch(err){
  if(state.user){
   state.user=null;
   state.csrf='';
   authPage('login');
   $('#auth-error').textContent=err.message;
   return;
  }
  if($('#auth-error'))return;
 }
 if(location.pathname==='/register')authPage('register');
 else if(location.pathname==='/login'||location.pathname==='/app')authPage('login');
 else landing();
}
start();

async function recordServer(){
 stopVoice();const epoch=state.voiceEpoch;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('This browser cannot record audio here. Type your answer.');return;}
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(epoch!==state.voiceEpoch||!$('#transcript')){stream.getTracks().forEach(t=>t.stop());return;}state.stream=stream;state.discardRecording=false;const chunks=[];let size=0;const recorder=state.recorder=new MediaRecorder(stream);
 recorder.ondataavailable=event=>{if(event.data.size){size+=event.data.size;chunks.push(event.data);if(size>8*1024*1024){state.discardRecording=true;recorder.stop();toast('Recording too large. Try a shorter answer.');}}};
 recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());clearTimeout(state.recordTimer);state.stream=null;state.recorder=null;$('#voice-orb')?.classList.remove('listening');if(epoch!==state.voiceEpoch||state.discardRecording||!$('#transcript'))return;$('#voice-status').textContent='Transcribing…';try{const form=new FormData();form.append('file',new Blob(chunks,{type:recorder.mimeType}),'recording.webm');const r=await api(`/courses/${state.cid}/speech/transcribe`,{method:'POST',body:form});if(epoch===state.voiceEpoch&&$('#transcript')){$('#transcript').value=r.text;$('#voice-status').textContent='Review your transcript, then submit.';}}catch(err){toast(err.message);if($('#voice-status'))$('#voice-status').textContent='Type your answer to continue.';}};
 recorder.start(1000);state.recordTimer=setTimeout(()=>{if(recorder.state!=='inactive')recorder.stop();},60000);$('#voice-status').textContent='Listening · maximum 60 seconds';$('#voice-orb').classList.add('listening');
 }catch{stopVoice();toast('Microphone permission denied or unavailable. Type your answer instead.');}
}
async function speakServer(text){stopVoice();const epoch=state.voiceEpoch;try{if($('#voice-status'))$('#voice-status').textContent='Preparing speech…';const r=await fetch(`/api/courses/${state.cid}/speech/synthesize`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({text})});if(!r.ok)throw Error('Speech provider unavailable. Read the visible text.');const blob=await r.blob();if(epoch!==state.voiceEpoch)return;const url=state.audioUrl=URL.createObjectURL(blob);const audio=state.audio=new Audio(url);audio.onended=()=>{URL.revokeObjectURL(url);state.audio=null;if($('#voice-status'))$('#voice-status').textContent='Ready · microphone off';};audio.onerror=()=>{URL.revokeObjectURL(url);toast('Audio playback failed. Read the text.');};if($('#voice-status'))$('#voice-status').textContent='Speaking · microphone off';await audio.play();}catch(err){toast(err.message);}}
